'use strict';
function startVerifiedShootout(){live.phase='shootout';live.shootoutAt=0;live.regularFeed=$('#liveFeed').innerHTML;renderShootout()}
function advanceVerifiedShootout(){if(!live||live.ended)return;live.shootoutAt++;if(live.shootoutAt>=live.m.shootout.length){finishLive();return}renderShootout()}
function renderShootout(){const m=live.m,kicks=m.shootout.slice(0,live.shootoutAt),score=[m.home,m.away].map(team=>kicks.filter(k=>k.team===team&&k.outcome==='scored').length);$('#liveScore').innerHTML=m.hg+' <em>:</em> '+m.ag;$('#liveClock').innerHTML=live.ended?'승부차기 종료':'승부차기 <span>실제 킥 순서 · 시각 미복원</span>';let board=$('#shootoutScore');if(!board){board=document.createElement('div');board.id='shootoutScore';board.className='shootout-score';$('#liveClock').after(board)}board.innerHTML='<small>승부차기 · 경기 득점과 별도</small><b>'+score.join(' : ')+'</b><span>'+kicks.length+'회 진행</span>';$('#matchProgress').style.width='100%';$('#playLive').disabled=!live.ended;$('#playLive').textContent=live.ended?'↶ 다시 킥오프':'승부차기는 다음 킥 버튼으로 진행';$('#nextMoment').textContent=live.ended?'승부차기 완료':'다음 승부차기 →';$('#liveFeed').innerHTML=kicks.map((k,i)=>'<article class="live-event '+(k.outcome==='scored'?'goal':'save')+'"><span>PK '+(i+1)+'</span><div><small>승부차기 · '+(k.outcome==='scored'?'성공':k.outcome==='saved'?'골키퍼 선방':'실축')+'</small><p>'+esc(n(k.team))+' · '+esc(koreanPerson(k.player))+'</p></div></article>').reverse().join('')+live.regularFeed;if(!$('#shootoutEvidence'))$('#liveSide').insertAdjacentHTML('afterbegin','<p id="shootoutEvidence" class="archive-match-note">확인된 승부차기 순서를 한 킥씩 공개합니다. 기록에 없는 준비 시간과 심리 묘사는 만들지 않습니다. <a class="source-link" target="_blank" rel="noopener" href="'+esc(m.shootoutSource)+'">순서 근거 ↗</a></p>')}
